{
  "name": "AuditMatch Pro",
  "description": "A financial reconciliation tool to compare book accounting records against payment reports. Features intelligent filtering, gap analysis, and visual status reporting."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BookEntry {
  appId: string;
  debit: number; // Target price
  originalRow: any;
}

export interface PaymentEntry {
  appId: string;
  pricePaid: number;
  sourceFile: string;
}

export enum MatchStatus {
  JUSTIFIED = 'JUSTIFIED', // Green: Paid >= Target
  UNDERCHARGED = 'UNDERCHARGED', // Red: Paid < Target
  MISSING_PAYMENT = 'MISSING_PAYMENT', // In books, not in payment
  UNACCOUNTED = 'UNACCOUNTED', // In payment, not in books (optional context)
  IGNORED = 'IGNORED' // Filtered out (e.g. wrong digits)
}

export interface ReconciliationResult {
  appId: string;
  bookAmount: number;
  paymentAmount: number;
  difference: number; // payment - book
  status: MatchStatus;
  sources: string[];
}

export interface DashboardStats {
  totalBooksRecords: number;
  totalPaymentsRecords: number;
  totalJustified: number;
  totalUndercharged: number;
  totalMissing: number;
  totalRevenueCollected: number;
  totalTargetRevenue: number;
}

import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import { BookEntry, PaymentEntry } from '../types';

// Helper to clean currency strings to numbers
const parseCurrency = (value: any): number => {
  if (typeof value === 'number') return value;
  if (!value) return 0;
  const cleanStr = String(value).replace(/[^0-9.-]+/g, '');
  return parseFloat(cleanStr) || 0;
};

// Helper to normalize keys (remove whitespace, lowercase)
const normalizeKey = (key: string) => key.trim().toLowerCase();

export const parseBooksFile = (file: File): Promise<BookEntry[]> => {
  return new Promise((resolve, reject) => {
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const books: BookEntry[] = [];

        results.data.forEach((row: any) => {
          // Flexible key matching
          const keys = Object.keys(row);
          const accountKey = keys.find(k => normalizeKey(k).includes('account') || normalizeKey(k).includes('app id'));
          const debitKey = keys.find(k => normalizeKey(k) === 'debit' || normalizeKey(k).includes('target') || normalizeKey(k).includes('price'));

          if (accountKey && debitKey) {
            const appIdRaw = String(row[accountKey]).trim();
            const debit = parseCurrency(row[debitKey]);

            // Logic: Ignore any 10 digit or above data. Keep 5-9 digits.
            // Using Regex to strict match 5 to 9 digits.
            const isValidId = /^\d{5,9}$/.test(appIdRaw);

            if (isValidId) {
              books.push({
                appId: appIdRaw,
                debit: debit,
                originalRow: row
              });
            }
          }
        });
        resolve(books);
      },
      error: (error) => reject(error)
    });
  });
};

export const parsePaymentFile = (file: File): Promise<PaymentEntry[]> => {
  return new Promise((resolve, reject) => {
    const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');

    if (isExcel) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);

        const payments = processPaymentData(jsonData, file.name);
        resolve(payments);
      };
      reader.onerror = (err) => reject(err);
      reader.readAsBinaryString(file);
    } else {
      // Assume CSV
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          const payments = processPaymentData(results.data, file.name);
          resolve(payments);
        },
        error: (error) => reject(error)
      });
    }
  });
};

const processPaymentData = (data: any[], fileName: string): PaymentEntry[] => {
  const payments: PaymentEntry[] = [];

  data.forEach((row: any) => {
    const keys = Object.keys(row);
    // Looking for "app id" and "price paid"
    const appIdKey = keys.find(k => normalizeKey(k).includes('app id') || normalizeKey(k) === 'id');
    const priceKey = keys.find(k => normalizeKey(k).includes('price paid') || normalizeKey(k).includes('amount') || normalizeKey(k) === 'paid');

    if (appIdKey && priceKey) {
      const appIdRaw = String(row[appIdKey]).trim();
      const pricePaid = parseCurrency(row[priceKey]);

      // Note: Payment files might not need strict 5-9 digit filtering unless specified, 
      // but usually we want to match against books. We will allow all here and filter during reconciliation.
      if (appIdRaw) {
        payments.push({
          appId: appIdRaw,
          pricePaid: pricePaid,
          sourceFile: fileName
        });
      }
    }
  });

  return payments;
};

import { BookEntry, PaymentEntry, ReconciliationResult, MatchStatus, DashboardStats } from '../types';

export const reconcileData = (books: BookEntry[], payments: PaymentEntry[]): { results: ReconciliationResult[], stats: DashboardStats } => {

  // 1. Aggregate Payments by App ID
  const paymentMap = new Map<string, { totalPaid: number, sources: Set<string> }>();

  payments.forEach(p => {
    const existing = paymentMap.get(p.appId) || { totalPaid: 0, sources: new Set<string>() };
    existing.totalPaid += p.pricePaid;
    existing.sources.add(p.sourceFile);
    paymentMap.set(p.appId, existing);
  });

  const results: ReconciliationResult[] = [];
  let totalJustified = 0;
  let totalUndercharged = 0;
  let totalMissing = 0;
  let totalRevenueCollected = 0;
  let totalTargetRevenue = 0;

  // 2. Iterate Books (Source of Truth)
  books.forEach(book => {
    const paymentData = paymentMap.get(book.appId);
    const amountPaid = paymentData ? paymentData.totalPaid : 0;
    const sources = paymentData ? Array.from(paymentData.sources) : [];

    let status: MatchStatus;

    // Logic: 
    // - Green if Price Charged (Paid) >= Target Price (Debit)
    // - Red if Price Charged < Target Price
    // - Alert if Missing (Paid is 0 but Debit > 0)

    if (amountPaid >= book.debit) {
      status = MatchStatus.JUSTIFIED;
      totalJustified++;
    } else if (amountPaid === 0) {
      status = MatchStatus.MISSING_PAYMENT;
      totalMissing++;
    } else {
      status = MatchStatus.UNDERCHARGED;
      totalUndercharged++;
    }

    totalTargetRevenue += book.debit;
    totalRevenueCollected += amountPaid;

    results.push({
      appId: book.appId,
      bookAmount: book.debit,
      paymentAmount: amountPaid,
      difference: amountPaid - book.debit,
      status,
      sources
    });

    // Remove from map to track unaccounted payments later if needed
    // paymentMap.delete(book.appId); 
  });

  // Optional: Handle payments that don't exist in books? 
  // The prompt implies we are auditing "wether i had charged justifieable as per books", 
  // so the Book list is the primary driver. We can ignore "Unaccounted" for now to keep the UI focused.

  const stats: DashboardStats = {
    totalBooksRecords: books.length,
    totalPaymentsRecords: payments.length,
    totalJustified,
    totalUndercharged,
    totalMissing,
    totalRevenueCollected,
    totalTargetRevenue
  };

  return { results, stats };
};

import React, { useRef, useState } from 'react';
import { Upload, FileSpreadsheet, X, CheckCircle2 } from 'lucide-react';

interface FileUploadProps {
  label: string;
  subLabel: string;
  accept: string;
  multiple?: boolean;
  onFilesSelected: (files: File[]) => void;
  files: File[];
  onRemoveFile: (index: number) => void;
  colorClass?: string;
}

export const FileUpload: React.FC<FileUploadProps> = ({ 
  label, 
  subLabel, 
  accept, 
  multiple = false, 
  onFilesSelected, 
  files, 
  onRemoveFile,
  colorClass = "blue"
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      onFilesSelected(Array.from(e.dataTransfer.files));
    }
  };

  const handleClick = () => {
    inputRef.current?.click();
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFilesSelected(Array.from(e.target.files));
    }
    // Reset value to allow re-upload of same file
    if (inputRef.current) inputRef.current.value = '';
  };

  const bgColor = isDragging ? `bg-${colorClass}-50` : 'bg-white';
  const borderColor = isDragging ? `border-${colorClass}-500` : 'border-slate-200';
  const textColor = `text-${colorClass}-600`;

  return (
    <div className="w-full">
      <div 
        className={`relative border-2 border-dashed ${borderColor} ${bgColor} rounded-xl p-6 transition-all duration-200 ease-in-out hover:border-${colorClass}-400 cursor-pointer group`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClick}
      >
        <input 
          ref={inputRef} 
          type="file" 
          accept={accept} 
          multiple={multiple} 
          className="hidden" 
          onChange={handleChange} 
        />

        <div className="flex flex-col items-center justify-center text-center space-y-3">
          <div className={`p-3 rounded-full bg-${colorClass}-50 group-hover:bg-${colorClass}-100 transition-colors`}>
            <Upload className={`w-6 h-6 ${textColor}`} />
          </div>
          <div>
            <p className="text-sm font-semibold text-slate-700">{label}</p>
            <p className="text-xs text-slate-500 mt-1">{subLabel}</p>
          </div>
        </div>
      </div>

      {files.length > 0 && (
        <div className="mt-4 space-y-2">
          <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Selected Files</p>
          {files.map((file, idx) => (
            <div key={idx} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-lg shadow-sm">
              <div className="flex items-center space-x-3">
                <FileSpreadsheet className="w-5 h-5 text-slate-400" />
                <div>
                  <p className="text-sm font-medium text-slate-700 truncate max-w-[200px]">{file.name}</p>
                  <p className="text-xs text-slate-400">{(file.size / 1024).toFixed(1)} KB</p>
                </div>
              </div>
              <button 
                onClick={(e) => { e.stopPropagation(); onRemoveFile(idx); }}
                className="p-1 hover:bg-slate-100 rounded-full text-slate-400 hover:text-red-500 transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { ReconciliationResult, DashboardStats, MatchStatus } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AlertCircle, CheckCircle2, DollarSign, FileWarning, Download } from 'lucide-react';

interface DashboardProps {
  results: ReconciliationResult[];
  stats: DashboardStats;
}

export const Dashboard: React.FC<DashboardProps> = ({ results, stats }) => {
  const [filter, setFilter] = useState<MatchStatus | 'ALL'>('ALL');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredResults = useMemo(() => {
    return results.filter(r => {
      const matchesFilter = filter === 'ALL' || r.status === filter;
      const matchesSearch = r.appId.includes(searchTerm);
      return matchesFilter && matchesSearch;
    });
  }, [results, filter, searchTerm]);

  const pieData = [
    { name: 'Justified', value: stats.totalJustified, color: '#10b981' }, // Emerald-500
    { name: 'Undercharged', value: stats.totalUndercharged, color: '#f43f5e' }, // Rose-500
    { name: 'Missing', value: stats.totalMissing, color: '#f59e0b' }, // Amber-500
  ].filter(d => d.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
  };

  const downloadCSV = () => {
    const headers = ['App ID', 'Target (Book)', 'Paid', 'Difference', 'Status', 'Sources'];
    const csvContent = [
      headers.join(','),
      ...filteredResults.map(r => [
        r.appId,
        r.bookAmount,
        r.paymentAmount,
        r.difference,
        r.status,
        `"${r.sources.join('; ')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', 'audit_report.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Revenue Collected" 
          value={formatCurrency(stats.totalRevenueCollected)} 
          subValue={`Target: ${formatCurrency(stats.totalTargetRevenue)}`}
          icon={<DollarSign className="w-5 h-5 text-blue-600" />}
          trend={stats.totalRevenueCollected >= stats.totalTargetRevenue ? 'up' : 'down'}
        />
        <StatCard 
          title="Justified Records" 
          value={stats.totalJustified.toString()} 
          subValue="Fully paid or overpaid"
          icon={<CheckCircle2 className="w-5 h-5 text-emerald-600" />}
          color="emerald"
        />
        <StatCard 
          title="Undercharged" 
          value={stats.totalUndercharged.toString()} 
          subValue="Paid less than target"
          icon={<AlertCircle className="w-5 h-5 text-rose-600" />}
          color="rose"
        />
        <StatCard 
          title="Missing Payments" 
          value={stats.totalMissing.toString()} 
          subValue="No payment found"
          icon={<FileWarning className="w-5 h-5 text-amber-600" />}
          color="amber"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm lg:col-span-1">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Status Distribution</h3>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Top 10 Undercharged Apps</h3>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={results
                  .filter(r => r.difference < 0)
                  .sort((a, b) => a.difference - b.difference) // Sort by biggest negative difference
                  .slice(0, 10)}
                layout="vertical"
                margin={{ top: 5, right: 30, left: 40, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} />
                <XAxis type="number" />
                <YAxis dataKey="appId" type="category" width={80} />
                <Tooltip formatter={(value) => formatCurrency(Number(value))} />
                <Bar dataKey="difference" fill="#f43f5e" radius={[0, 4, 4, 0]} name="Deficit" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Detailed Table */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-5 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <h3 className="text-lg font-bold text-slate-800">Audit Details</h3>

          <div className="flex flex-col sm:flex-row gap-3">
             <input 
              type="text" 
              placeholder="Search App ID..." 
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <select 
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
              value={filter}
              onChange={(e) => setFilter(e.target.value as any)}
            >
              <option value="ALL">All Statuses</option>
              <option value={MatchStatus.JUSTIFIED}>Justified (Green)</option>
              <option value={MatchStatus.UNDERCHARGED}>Undercharged (Red)</option>
              <option value={MatchStatus.MISSING_PAYMENT}>Missing Payment</option>
            </select>
            <button 
              onClick={downloadCSV}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors"
            >
              <Download className="w-4 h-4" /> Export
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-3 font-medium">App ID</th>
                <th className="px-6 py-3 font-medium text-right">Target (Book)</th>
                <th className="px-6 py-3 font-medium text-right">Paid</th>
                <th className="px-6 py-3 font-medium text-right">Difference</th>
                <th className="px-6 py-3 font-medium text-center">Status</th>
                <th className="px-6 py-3 font-medium">Source Files</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredResults.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-8 text-center text-slate-500">
                    No records found matching criteria.
                  </td>
                </tr>
              ) : (
                filteredResults.map((row) => (
                  <tr key={row.appId} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-900">{row.appId}</td>
                    <td className="px-6 py-4 text-right font-mono text-slate-600">{formatCurrency(row.bookAmount)}</td>
                    <td className="px-6 py-4 text-right font-mono text-slate-600">{formatCurrency(row.paymentAmount)}</td>
                    <td className={`px-6 py-4 text-right font-mono font-medium ${row.difference >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {row.difference > 0 ? '+' : ''}{formatCurrency(row.difference)}
                    </td>
                    <td className="px-6 py-4 text-center">
                      <StatusBadge status={row.status} />
                    </td>
                    <td className="px-6 py-4 text-slate-500 truncate max-w-xs" title={row.sources.join(', ')}>
                      {row.sources.length > 0 ? row.sources.join(', ') : '-'}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 text-xs text-slate-500 flex justify-between">
          <span>Showing {filteredResults.length} records</span>
          <span>Filtered from {results.length} total</span>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ title: string, value: string, subValue: string, icon: React.ReactNode, trend?: 'up' | 'down', color?: string }> = ({ title, value, subValue, icon, trend, color }) => (
  <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between h-full">
    <div className="flex justify-between items-start mb-4">
      <div className={`p-2 rounded-lg bg-${color || 'slate'}-50`}>
        {icon}
      </div>
      {trend && (
        <span className={`text-xs font-bold px-2 py-1 rounded-full ${trend === 'up' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
          {trend === 'up' ? 'Surplus' : 'Deficit'}
        </span>
      )}
    </div>
    <div>
      <h4 className="text-slate-500 text-sm font-medium mb-1">{title}</h4>
      <p className="text-2xl font-bold text-slate-800">{value}</p>
      <p className="text-xs text-slate-400 mt-1">{subValue}</p>
    </div>
  </div>
);

const StatusBadge: React.FC<{ status: MatchStatus }> = ({ status }) => {
  switch (status) {
    case MatchStatus.JUSTIFIED:
      return (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-100 text-emerald-700">
          <CheckCircle2 className="w-3.5 h-3.5" /> Justified
        </span>
      );
    case MatchStatus.UNDERCHARGED:
      return (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-rose-100 text-rose-700">
          <AlertCircle className="w-3.5 h-3.5" /> Alert
        </span>
      );
    case MatchStatus.MISSING_PAYMENT:
      return (
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-amber-100 text-amber-700">
          <FileWarning className="w-3.5 h-3.5" /> Missing
        </span>
      );
    default:
      return <span className="text-slate-500">-</span>;
  }
};

import React, { useState, useEffect } from 'react';
import { BookEntry, PaymentEntry, ReconciliationResult, DashboardStats } from './types';
import { parseBooksFile, parsePaymentFile } from './services/parserService';
import { reconcileData } from './services/reconciliationService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';
import { ShieldCheck, RefreshCw, ChevronRight, LayoutDashboard, FileText } from 'lucide-react';

const App: React.FC = () => {
  // State for files
  const [booksFile, setBooksFile] = useState<File | null>(null);
  const [paymentFiles, setPaymentFiles] = useState<File[]>([]);

  // State for processed data
  const [results, setResults] = useState<ReconciliationResult[]>([]);
  const [stats, setStats] = useState<DashboardStats | null>(null);

  // Loading and Error states
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [step, setStep] = useState<1 | 2>(1); // 1 = Upload, 2 = Dashboard

  const handleBooksUpload = (files: File[]) => {
    if (files.length > 0) setBooksFile(files[0]);
  };

  const handlePaymentsUpload = (files: File[]) => {
    setPaymentFiles(prev => [...prev, ...files]);
  };

  const removeBookFile = () => setBooksFile(null);
  const removePaymentFile = (index: number) => {
    setPaymentFiles(prev => prev.filter((_, i) => i !== index));
  };

  const processReconciliation = async () => {
    if (!booksFile || paymentFiles.length === 0) {
      setError("Please upload the Books file and at least one Payment file.");
      return;
    }

    setIsProcessing(true);
    setError(null);

    try {
      // 1. Parse Books
      const booksData = await parseBooksFile(booksFile);

      // 2. Parse Payments (Parallel)
      const paymentPromises = paymentFiles.map(file => parsePaymentFile(file));
