import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import { BookEntry, PaymentEntry } from '../types';

// Helper to clean currency strings to numbers
const parseCurrency = (value: any): number => {
  if (typeof value === 'number') return value;
  if (!value) return 0;
  // Handle "1,200.00 Dr" or similar formats
  const cleanStr = String(value).replace(/[^0-9.-]+/g, '');
  return parseFloat(cleanStr) || 0;
};

// Helper to normalize keys
const normalizeKey = (key: string) => key.trim().toLowerCase();

export const parseBooksFile = (file: File): Promise<BookEntry[]> => {
  return new Promise((resolve, reject) => {
    Papa.parse(file, {
      header: false, // Parse as arrays to find the dynamic header row
      skipEmptyLines: true,
      complete: (results) => {
        const rows = results.data as string[][];
        const books: BookEntry[] = [];

        let debitIndex = -1;
        let headerFound = false;

        // Scan for header row
        for (let i = 0; i < rows.length; i++) {
          const row = rows[i].map(c => normalizeKey(String(c)));

          // Identify header by looking for key columns
          if (row.some(c => c.includes('date')) && (row.some(c => c.includes('debit')) || row.some(c => c.includes('particulars')))) {
            // Find specific index for Debit
            row.forEach((cell, idx) => {
              if (cell.includes('debit')) debitIndex = idx;
            });

            if (debitIndex !== -1) {
              headerFound = true;
              // Start processing from next row
              processBookRows(rows.slice(i + 1), debitIndex, books);
              break; 
            }
          }
        }

        if (!headerFound) {
           // Fallback: If no complex header found, try to parse with standard headers (user might upload cleaned csv)
           // But given the prompt, we assume the specific format.
           // Let's try to assume a standard structure if header scan failed, assuming headers are on row 0
           const firstRow = rows[0].map(c => normalizeKey(String(c)));
           firstRow.forEach((cell, idx) => {
              if (cell.includes('debit') || cell.includes('amount') || cell.includes('price')) debitIndex = idx;
           });
           if (debitIndex !== -1) {
              processBookRows(rows.slice(1), debitIndex, books);
           } else {
              reject(new Error("Could not find 'Debit' column in the Books file. Please ensure the file format is correct."));
              return;
           }
        }

        resolve(books);
      },
      error: (error) => reject(error)
    });
  });
};

const processBookRows = (rows: string[][], debitIndex: number, books: BookEntry[]) => {
  rows.forEach(row => {
    if (!row[debitIndex]) return;

    const debitRaw = row[debitIndex];
    const debit = parseCurrency(debitRaw);

    // Only consider rows with a valid Debit amount (ignore Credits/Journals without debit)
    if (debit <= 0) return;

    // Search for App ID (5-9 digits) in the entire row text
    // We join the row to search everywhere, but excluding the debit value itself avoids false positives if debit matches strict digits (unlikely for price)
    // Actually, price usually has decimals or is small, App ID is 5-9 digits. 
    // Safest is to exclude the debit column from search.
    const textToSearch = row.filter((_, idx) => idx !== debitIndex).join(' ');

    // Regex Explanation:
    // \b       : Word boundary
    // \d{5,9}  : 5 to 9 digits
    // \b       : Word boundary
    // This strictly ignores 4 digit years (2025) and 10 digit phone numbers.
    const matches = textToSearch.match(/\b\d{5,9}\b/g);

    if (matches && matches.length > 0) {
      // Assuming the first match is the App ID. 
      // In conflict cases, we take the one that looks most like an ID. 
      // Given the data, 6 or 8 digits seem common.
      const appId = matches[0];

      books.push({
        appId: appId,
        debit: debit,
        originalRow: row
      });
    }
  });
};

export const parsePaymentFile = (file: File): Promise<PaymentEntry[]> => {
  return new Promise((resolve, reject) => {
    const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');

    if (isExcel) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);

        const payments = processPaymentData(jsonData, file.name);
        resolve(payments);
      };
      reader.onerror = (err) => reject(err);
      reader.readAsBinaryString(file);
    } else {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          const payments = processPaymentData(results.data, file.name);
          resolve(payments);
        },
        error: (error) => reject(error)
      });
    }
  });
};

const processPaymentData = (data: any[], fileName: string): PaymentEntry[] => {
  const payments: PaymentEntry[] = [];

  data.forEach((row: any) => {
    const keys = Object.keys(row);
    // Flexible Key Matching
    const appIdKey = keys.find(k => {
      const norm = normalizeKey(k);
      return norm.includes('app id') || norm.includes('application no') || norm === 'id' || norm.includes('application_no');
    });

    const priceKey = keys.find(k => {
      const norm = normalizeKey(k);
      return norm.includes('price paid') || norm.includes('price incl') || norm.includes('amount') || norm.includes('paid');
    });

    if (appIdKey && priceKey) {
      const appIdRaw = String(row[appIdKey]).trim();
      const pricePaid = parseCurrency(row[priceKey]);

      if (appIdRaw) {
        payments.push({
          appId: appIdRaw,
          pricePaid: pricePaid,
          sourceFile: fileName
        });
      }
    }
  });

  return payments;
};

import React, { useRef, useState } from 'react';
