import React, { useState, useEffect } from 'react';
import { BookEntry, PaymentEntry, ReconciliationResult, DashboardStats } from './types';
import { parseBooksFile, parsePaymentFile } from './services/parserService';
import { reconcileData } from './services/reconciliationService';
import { FileUpload } from './components/FileUpload';
import { Dashboard } from './components/Dashboard';
import { ShieldCheck, RefreshCw, ChevronRight, LayoutDashboard, FileText } from 'lucide-react';

const App: React.FC = () => {
  // State for files
  const [booksFile, setBooksFile] = useState<File | null>(null);
  const [paymentFiles, setPaymentFiles] = useState<File[]>([]);

  // State for processed data
  const [results, setResults] = useState<ReconciliationResult[]>([]);
  // Stats are now computed inside Dashboard dynamically

  // Loading and Error states
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [step, setStep] = useState<1 | 2>(1); // 1 = Upload, 2 = Dashboard

  const handleBooksUpload = (files: File[]) => {
    if (files.length > 0) setBooksFile(files[0]);
  };

  const handlePaymentsUpload = (files: File[]) => {
    setPaymentFiles(prev => [...prev, ...files]);
  };

  const removeBookFile = () => setBooksFile(null);
  const removePaymentFile = (index: number) => {
    setPaymentFiles(prev => prev.filter((_, i) => i !== index));
  };

  const processReconciliation = async () => {
    if (!booksFile || paymentFiles.length === 0) {
      setError("Please upload the Books file and at least one Payment file.");
      return;
    }

    setIsProcessing(true);
    setError(null);

    try {
      // 1. Parse Books
      const booksData = await parseBooksFile(booksFile);

      // 2. Parse Payments (Parallel)
      const paymentPromises = paymentFiles.map(file => parsePaymentFile(file));
      const paymentArrays = await Promise.all(paymentPromises);
      const flatPayments = paymentArrays.flat();

      // 3. Reconcile
      const { results: recoResults } = reconcileData(booksData, flatPayments);

      setResults(recoResults);
      setStep(2);
    } catch (err: any) {
      console.error(err);
      setError("Error processing files. Please ensure the 'Books' file has a 'Debit' column and ID in narration, and 'Payment' files have 'Application No' and 'Price' columns.");
    } finally {
      setIsProcessing(false);
    }
  };

  const reset = () => {
    setResults([]);
    setStep(1);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <ShieldCheck className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500">
              AuditMatch Pro
            </h1>
          </div>
          {step === 2 && (
            <button 
              onClick={reset}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 hover:text-blue-600 transition-colors"
            >
              <RefreshCw className="w-4 h-4" /> Start New Audit
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {step === 1 && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-slate-900">Upload Financial Records</h2>
              <p className="mt-3 text-lg text-slate-500">Compare your internal OFA books against Platinum portal payment reports to identify discrepancies instantly.</p>
            </div>

            <div className="space-y-8">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">1</div>
                  <h3 className="text-lg font-semibold text-slate-800">OFA Books Export</h3>
                </div>
                <FileUpload 
                  label="Upload OFA Books CSV" 
                  subLabel="Exports with 'Debit' amount and App ID (5-9 digits) in Narration" 
                  accept=".csv"
                  files={booksFile ? [booksFile] : []}
                  onFilesSelected={handleBooksUpload}
                  onRemoveFile={removeBookFile}
                  colorClass="blue"
                />
              </div>

              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-8 h-8 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600 font-bold">2</div>
                  <h3 className="text-lg font-semibold text-slate-800">Platinum / Portal Exports</h3>
                </div>
                <FileUpload 
                  label="Upload Platinum/Portal Files" 
                  subLabel="Multiple files containing 'Application No' and 'Price incl of GST'" 
                  accept=".csv,.xlsx,.xls"
                  multiple={true}
                  files={paymentFiles}
                  onFilesSelected={handlePaymentsUpload}
                  onRemoveFile={removePaymentFile}
                  colorClass="emerald"
                />
              </div>

              {error && (
                <div className="p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg flex items-center gap-3">
                  <ShieldCheck className="w-5 h-5" />
                  {error}
                </div>
              )}

              <div className="flex justify-end">
                <button
                  onClick={processReconciliation}
                  disabled={isProcessing || !booksFile || paymentFiles.length === 0}
                  className={`
                    flex items-center gap-2 px-8 py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-500/20 transition-all
                    ${isProcessing || !booksFile || paymentFiles.length === 0
                      ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                      : 'bg-blue-600 text-white hover:bg-blue-700 hover:shadow-blue-500/30 transform hover:-translate-y-0.5'}
                  `}
                >
                  {isProcessing ? (
                    <>
                      <RefreshCw className="w-5 h-5 animate-spin" /> Processing...
                    </>
                  ) : (
                    <>
                      Run Audit <ChevronRight className="w-5 h-5" />
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        )}

        {step === 2 && (
          <Dashboard results={results} />
        )}
      </main>
    </div>
  );
};

