// Helper to clean currency strings to numbers
const parseCurrency = (value: any): number => {
  if (typeof value === 'number') return value;
  if (!value) return 0;
  const cleanStr = String(value).replace(/[^0-9.-]+/g, '');
  return parseFloat(cleanStr) || 0;
};

// Helper to normalize keys
const normalizeKey = (key: string) => key.trim().toLowerCase();

// Date Parser: Supports DD-MM-YYYY, YYYY-MM-DD, MM/DD/YYYY
const parseDate = (value: any): Date | null => {
  if (!value) return null;
  if (value instanceof Date) return value;

  const str = String(value).trim();
  if (!str) return null;

  // Excel serial dates (numbers)
  if (!isNaN(Number(str)) && !str.includes('-') && !str.includes('/')) {
     // Excel base date is roughly 1900-01-01. simplified conversion:
     const excelDate = new Date((Number(str) - (25567 + 2)) * 86400 * 1000);
     return excelDate;
  }

  // Try standard date parse
  let date = new Date(str);
  if (!isNaN(date.getTime())) return date;

  // Try parsing DD-MM-YYYY or DD/MM/YYYY (Common in India/UK)
  const parts = str.split(/[-/.]/);
  if (parts.length === 3) {
    // Assumption: If first part > 12, it's definitely day (or year, but year is usually 4 digits)
    // If year is last (4 digits)
    if (parts[2].length === 4) {
      // DD-MM-YYYY
      const day = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const year = parseInt(parts[2], 10);
      date = new Date(year, month, day);
      if (!isNaN(date.getTime())) return date;
    }
  }

  return null;
};

// Generic Raw Parser
export const parseRawCsv = (file: File): Promise<{ headers: string[], rows: any[] }> => {
  return new Promise((resolve, reject) => {
    Papa.parse(file, {
      header: false,
      skipEmptyLines: true,
      complete: (results) => {
        const rows = results.data as string[][];
        if (rows.length === 0) {
          resolve({ headers: [], rows: [] });
          return;
        }

        // Auto-detect header row
        // Look for common keywords like "Date", "Debit", "Amount", "App ID"
        let headerIndex = 0;
        let bestScore = 0;

        rows.slice(0, 10).forEach((row, idx) => {
          let score = 0;
          const normRow = row.map(c => normalizeKey(String(c)));
          if (normRow.some(c => c.includes('date'))) score++;
          if (normRow.some(c => c.includes('amount') || c.includes('debit') || c.includes('price'))) score++;
          if (normRow.some(c => c.includes('id') || c.includes('account') || c.includes('particulars'))) score++;

          if (score > bestScore) {
            bestScore = score;
            headerIndex = idx;
          }
        });

        const headers = rows[headerIndex].map(h => String(h).trim());
        const dataRows = rows.slice(headerIndex + 1).map(row => {
            // Map array back to object based on headers for easier consumption later if needed
            // But we will stick to array index mapping for robustness
            const obj: any = {};
            headers.forEach((h, i) => {
                obj[h] = row[i];
            });
            return obj;
        });

        resolve({ headers, rows: dataRows });
      },
      error: (err) => reject(err)
    });
  });
};

export const parseRawExcel = (file: File): Promise<{ headers: string[], rows: any[] }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

        if (jsonData.length === 0) {
            resolve({ headers: [], rows: [] });
            return;
        }

        // Basic header detection (row 0)
        const headers = jsonData[0].map(h => String(h).trim());
        const rows = jsonData.slice(1).map(row => {
             const obj: any = {};
             headers.forEach((h, i) => {
                 obj[h] = row[i];
             });
             return obj;
        });
        resolve({ headers, rows });
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsBinaryString(file);
  });
};

// Data Extractors using Mappings

export const extractBookData = (rows: any[], mapping: ColumnMapping): BookEntry[] => {
  const books: BookEntry[] = [];

  rows.forEach(row => {
    const debit = parseCurrency(row[mapping.amount]);
    const date = parseDate(row[mapping.date]);

    // For App ID, if the column selected is "Narrartion/Particulars", we might need regex
    // If it's a direct ID column, use it directly.
    let appId = String(row[mapping.appId] || '').trim();

    // Heuristic: If ID field is long (likely narration), try regex
    if (appId.length > 15 || appId.includes(' ')) {
       const matches = appId.match(/\b\d{5,9}\b/g);
       if (matches && matches.length > 0) {
         appId = matches[0];
       } else {
         // If no regex match in mapping col, try searching entire row as fallback? 
         // For now, strict mapping.
         return; 
       }
    }

    if (debit > 0 && appId && /^\d{5,9}$/.test(appId)) {
      books.push({
        appId,
        debit,
        date,
        originalRow: row
      });
    }
  });

  return books;
};

export const extractPaymentData = (rows: any[], mapping: ColumnMapping, fileName: string): PaymentEntry[] => {
  const payments: PaymentEntry[] = [];

  rows.forEach(row => {
    const pricePaid = parseCurrency(row[mapping.amount]);
    const date = parseDate(row[mapping.date]);
    let appId = String(row[mapping.appId] || '').trim();

    // Clean App ID
    appId = appId.replace(/[^0-9]/g, '');

    if (appId && /^\d{5,9}$/.test(appId)) {
      payments.push({
        appId,
        pricePaid,
        date,
        sourceFile: fileName
      });
    }
  });

  return payments;
};

// Auto-guesser for mapping
export const guessMapping = (headers: string[]): ColumnMapping => {
  const mapping: ColumnMapping = { date: '', appId: '', amount: '' };

  headers.forEach(h => {
    const lower = h.toLowerCase();
    if (!mapping.date && (lower.includes('date') || lower.includes('time'))) mapping.date = h;
    if (!mapping.amount && (lower.includes('debit') || lower.includes('price') || lower.includes('amount') || lower.includes('paid'))) mapping.amount = h;
    if (!mapping.appId && (lower.includes('id') || lower.includes('account') || lower.includes('particulars') || lower.includes('application'))) mapping.appId = h;
  });

  // Fallbacks if not found (pick first/second etc is risky, just leave blank for user)
  return mapping;
};

import { BookEntry, PaymentEntry, ReconciliationResult, MatchStatus, DashboardStats } from '../types';

export const reconcileData = (books: BookEntry[], payments: PaymentEntry[]): { results: ReconciliationResult[], stats: DashboardStats } => {

  // 1. Group Payments
  // Note: We need to check dates against specific book entries. 
  // Since one App ID usually corresponds to one main transaction in this context, 
  // but logically could have multiple, we will group all payments for an AppID first,
  // then filter them during the book iteration.

  const paymentMap = new Map<string, PaymentEntry[]>();

  payments.forEach(p => {
    const list = paymentMap.get(p.appId) || [];
    list.push(p);
    paymentMap.set(p.appId, list);
  });

  const results: ReconciliationResult[] = [];
  let totalMatched = 0;
  let totalOverpaid = 0;
  let totalMissing = 0;
  let totalRevenueCollected = 0;
  let totalTargetRevenue = 0;

  // 2. Iterate Books
  books.forEach(book => {
    const potentialPayments = paymentMap.get(book.appId) || [];

    // Date Condition: Payment Date >= Book Date
    // If dates are missing, we assume valid match to avoid false negatives on bad data
    const validPayments = potentialPayments.filter(p => {
      if (!book.date || !p.date) return true;
      // Normalize time for comparison
      const bDate = new Date(book.date); bDate.setHours(0,0,0,0);
      const pDate = new Date(p.date); pDate.setHours(0,0,0,0);
      return pDate >= bDate;
    });

    const amountPaid = validPayments.reduce((sum, p) => sum + p.pricePaid, 0);
    const sources = Array.from(new Set(validPayments.map(p => p.sourceFile)));

    let status: MatchStatus;

    // Logic requested:
    // If Paid (Net) > Book => Red (Overpaid/Error)
    // If Paid (Net) <= Book => Green (Matched)
    // If Paid == 0 => Yellow (Missing)

    // Note: Net calculation happens in UI/Dashboard. Here we use Gross/Raw.
    // We set a baseline status based on raw values.
    if (amountPaid === 0) {
      status = MatchStatus.MISSING_PAYMENT;
      totalMissing++;
    } else if (amountPaid > book.debit) {
      status = MatchStatus.OVERPAID;
      totalOverpaid++;
    } else {
      status = MatchStatus.MATCHED;
      totalMatched++;
    }

    totalTargetRevenue += book.debit;
    totalRevenueCollected += amountPaid;

    results.push({
      appId: book.appId,
      bookAmount: book.debit,
      paymentAmount: amountPaid,
      difference: amountPaid - book.debit,
      status,
      sources,
      bookDate: book.date
    });
  });

  const stats: DashboardStats = {
    totalBooksRecords: books.length,
    totalPaymentsRecords: payments.length,
    totalMatched,
    totalOverpaid,
    totalMissing,
    totalRevenueCollected,
    totalTargetRevenue
  };

  return { results, stats };
};

