import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import { BookEntry, PaymentEntry, ColumnMapping } from '../types';

// Helper to clean currency strings to numbers
const parseCurrency = (value: any): number => {
  if (typeof value === 'number') return value;
  if (!value) return 0;
  // Remove commas, currency symbols, and 'Dr'/'Cr' suffixes, keep dot and minus
  const cleanStr = String(value).replace(/[^0-9.-]+/g, '');
  return parseFloat(cleanStr) || 0;
};

// Helper to normalize keys
const normalizeKey = (key: string) => key.trim().toLowerCase();

// Date Parser: Supports DD-MM-YYYY, YYYY-MM-DD, MM/DD/YYYY, and DD-MMM-YYYY (09-Feb-2026)
const parseDate = (value: any): Date | null => {
  if (!value) return null;
  if (value instanceof Date) return value;

  const str = String(value).trim();
  if (!str) return null;

  // Excel serial dates (numbers)
  if (!isNaN(Number(str)) && !str.includes('-') && !str.includes('/')) {
     const excelDate = new Date((Number(str) - (25567 + 2)) * 86400 * 1000);
     return excelDate;
  }

  // Handle DD-MMM-YYYY (e.g. 09-Feb-2026) manually to be safe across browsers
  const monthNames = {jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11};
  const mmmMatch = str.match(/^(\d{1,2})[-/]([a-zA-Z]{3})[-/](\d{4})/);
  if (mmmMatch) {
    const day = parseInt(mmmMatch[1], 10);
    const monthStr = mmmMatch[2].toLowerCase();
    const year = parseInt(mmmMatch[3], 10);
    if (monthNames.hasOwnProperty(monthStr)) {
      return new Date(year, monthNames[monthStr as keyof typeof monthNames], day);
    }
  }

  // Try parsing DD-MM-YYYY or DD/MM/YYYY
  const parts = str.split(/[-/.]/);
  if (parts.length >= 3) {
    // Check if it looks like DD-MM-YYYY (Year is last and 4 digits)
    const p0 = parseInt(parts[0], 10);
    const p1 = parseInt(parts[1], 10);
    const p2 = parseInt(parts[2], 10);

    if (parts[2].length === 4 && !isNaN(p0) && !isNaN(p1) && !isNaN(p2)) {
       // Assumption: DD-MM-YYYY
       return new Date(p2, p1 - 1, p0);
    }
  }

  // Fallback to standard JS parsing
  const date = new Date(str);
  if (!isNaN(date.getTime())) return date;

  return null;
};

// Generic Raw Parser with Duplicate Header Handling
export const parseRawCsv = (file: File): Promise<{ headers: string[], rows: any[] }> => {
  return new Promise((resolve, reject) => {
    Papa.parse(file, {
      header: false,
      skipEmptyLines: true,
      complete: (results) => {
        const rows = results.data as string[][];
        if (rows.length === 0) {
          resolve({ headers: [], rows: [] });
          return;
        }

        // Auto-detect header row
        // Look for common keywords. Added 'narration' to help with OFA files.
        let headerIndex = 0;
        let bestScore = 0;

        rows.slice(0, 15).forEach((row, idx) => {
          let score = 0;
          const normRow = row.map(c => normalizeKey(String(c)));
          if (normRow.some(c => c.includes('date'))) score += 2;
          if (normRow.some(c => c.includes('amount') || c.includes('debit') || c.includes('price'))) score += 2;
          if (normRow.some(c => c.includes('id') || c.includes('account') || c.includes('particulars') || c.includes('narration'))) score += 2;

          if (score > bestScore) {
            bestScore = score;
            headerIndex = idx;
          }
        });

        const rawHeaders = rows[headerIndex].map(h => String(h).trim());

        // Handle Duplicate Headers (e.g. NARRATION, NARRATION) by appending suffix
        const headerCounts: Record<string, number> = {};
        const uniqueHeaders = rawHeaders.map(h => {
          const key = h || 'UNKNOWN';
          headerCounts[key] = (headerCounts[key] || 0) + 1;
          return headerCounts[key] > 1 ? `${key}_${headerCounts[key] - 1}` : key;
        });

        const dataRows = rows.slice(headerIndex + 1).map(row => {
            const obj: any = {};
            uniqueHeaders.forEach((h, i) => {
                obj[h] = row[i];
            });
            return obj;
        });

        resolve({ headers: uniqueHeaders, rows: dataRows });
      },
      error: (err) => reject(err)
    });
  });
};

export const parseRawExcel = (file: File): Promise<{ headers: string[], rows: any[] }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

        if (jsonData.length === 0) {
            resolve({ headers: [], rows: [] });
            return;
        }

        // Basic header detection (row 0)
        const rawHeaders = jsonData[0].map(h => String(h).trim());

        // Handle Duplicate Headers
        const headerCounts: Record<string, number> = {};
        const uniqueHeaders = rawHeaders.map(h => {
          const key = h || 'UNKNOWN';
          headerCounts[key] = (headerCounts[key] || 0) + 1;
          return headerCounts[key] > 1 ? `${key}_${headerCounts[key] - 1}` : key;
        });

        const rows = jsonData.slice(1).map(row => {
             const obj: any = {};
             uniqueHeaders.forEach((h, i) => {
                 obj[h] = row[i];
             });
             return obj;
        });
        resolve({ headers: uniqueHeaders, rows });
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsBinaryString(file);
  });
};

// Data Extractors using Mappings

export const extractBookData = (rows: any[], mapping: ColumnMapping): BookEntry[] => {
  const books: BookEntry[] = [];

  rows.forEach(row => {
    const debit = parseCurrency(row[mapping.amount]);
    const date = parseDate(row[mapping.date]);

    let rawAppId = String(row[mapping.appId] || '').trim();
    let appId = '';

    // Strategy:
    // 1. If strict 5-9 digits, use it.
    // 2. If it contains text (Narrations), use Regex.
    // 3. Regex must strictly match \b\d{5,9}\b to avoid 10-digit phone numbers.

    if (/^\d{5,9}$/.test(rawAppId)) {
        appId = rawAppId;
    } else {
        // Look for isolated 5-9 digit numbers.
        // \b matches boundary between \w and \W. 
        // 8757065466 is 10 digits. \b\d{5,9}\b will NOT match it because the 9th digit is followed by another digit (a \w character).
        const matches = rawAppId.match(/\b\d{5,9}\b/g);
        if (matches && matches.length > 0) {
            // If multiple matches, we take the first one. 
            // In the example: "8757065466 NIRAJ 11146737", the first number is 10 digits (ignored), second is 8 digits (matched).
            appId = matches[0];
        }
    }

    // Only add if we found a valid ID and Debit is > 0 (skips opening balances/headers inside data)
    if (debit > 0 && appId) {
      books.push({
        appId,
        debit,
        date,
        originalRow: row
      });
    }
  });

  return books;
};

export const extractPaymentData = (rows: any[], mapping: ColumnMapping, fileName: string): PaymentEntry[] => {
  const payments: PaymentEntry[] = [];

  rows.forEach(row => {
    const pricePaid = parseCurrency(row[mapping.amount]);
    const date = parseDate(row[mapping.date]);
    let appIdRaw = String(row[mapping.appId] || '').trim();

    // Clean App ID - for Payment files it's usually a direct column
    // but sometimes "Application No" might have spaces or weird chars
    const appId = appIdRaw.replace(/[^0-9]/g, '');

    if (appId && /^\d{5,9}$/.test(appId)) {
      payments.push({
        appId,
        pricePaid,
        date,
        sourceFile: fileName
      });
    }
  });

  return payments;
};

// Auto-guesser for mapping
export const guessMapping = (headers: string[]): ColumnMapping => {
  const mapping: ColumnMapping = { date: '', appId: '', amount: '' };

  headers.forEach(h => {
    const lower = h.toLowerCase();

    // Prioritize exact matches or strong keywords
    if (!mapping.date && (lower.includes('date') || lower.includes('time'))) mapping.date = h;

    if (!mapping.amount) {
        if (lower.includes('debit')) mapping.amount = h; // High priority for Books
        else if (lower.includes('price') || lower.includes('amount') || lower.includes('paid')) mapping.amount = h;
    }

    if (!mapping.appId) {
        if (lower.includes('application') && (lower.includes('id') || lower.includes('no'))) mapping.appId = h; // High priority for Portal
        else if (lower.includes('narration')) mapping.appId = h; // High priority for OFA Books
        else if (lower.includes('particulars') || lower.includes('account')) mapping.appId = h;
    }
  });

  return mapping;
};

import React, { useMemo, useState, useEffect } from 'react';
import { ReconciliationResult, MatchStatus, DashboardStats } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AlertCircle, CheckCircle2, DollarSign, FileWarning, Download, Percent, IndianRupee } from 'lucide-react';

interface DashboardProps {
  results: ReconciliationResult[];
}

interface ExtendedResult extends ReconciliationResult {
  discount: number;
  netPayment: number;
  computedDifference: number;
  computedStatus: MatchStatus;
}

export const Dashboard: React.FC<DashboardProps> = ({ results }) => {
  const [filter, setFilter] = useState<MatchStatus | 'ALL'>('ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [globalDiscount, setGlobalDiscount] = useState<string>('0');
  const [data, setData] = useState<ExtendedResult[]>([]);

  useEffect(() => {
    // Initial calculation based on Gross
    const initialData = results.map(r => {
      // Logic:
      // Red: Paid > Target (Overpaid)
      // Yellow: Paid == 0 (Missing)
      // Green: Paid <= Target (Matched) - includes underpaid
      let status = MatchStatus.MATCHED;
      if (r.paymentAmount > r.bookAmount) status = MatchStatus.OVERPAID;
      else if (r.paymentAmount === 0) status = MatchStatus.MISSING_PAYMENT;

      return {
        ...r,
        discount: 0,
        netPayment: r.paymentAmount,
        computedDifference: r.paymentAmount - r.bookAmount,
        computedStatus: status
      };
    });
    setData(initialData);
  }, [results]);

  const recalculateRow = (item: ExtendedResult, discountVal: number) => {
    const net = item.paymentAmount * (1 - discountVal / 100);
    const diff = net - item.bookAmount;

    let status = MatchStatus.MATCHED;
    if (net > item.bookAmount) status = MatchStatus.OVERPAID;
    else if (net === 0 && item.paymentAmount === 0) status = MatchStatus.MISSING_PAYMENT;
    // Note: If net becomes 0 due to 100% discount, it's technially "Matched" (paid 0 vs target X is underpaid, thus Green per request)
    // But logically, Missing means NO payment record found.
    // If payment found but discount makes it 0, it stays Green.

    return {
      ...item,
      discount: discountVal,
      netPayment: net,
      computedDifference: diff,
      computedStatus: status
    };
  };

  const applyGlobalDiscount = () => {
    const val = parseFloat(globalDiscount) || 0;
    setData(prev => prev.map(item => recalculateRow(item, val)));
  };

  const handleRowDiscountChange = (appId: string, valStr: string) => {
    const val = parseFloat(valStr) || 0;
    setData(prev => prev.map(item => item.appId === appId ? recalculateRow(item, val) : item));
  };

  const stats = useMemo(() => {
    const s: DashboardStats = {
      totalBooksRecords: data.length,
      totalPaymentsRecords: 0,
      totalMatched: 0,
      totalOverpaid: 0,
      totalMissing: 0,
      totalRevenueCollected: 0,
      totalTargetRevenue: 0
    };

    data.forEach(item => {
      s.totalRevenueCollected += item.netPayment;
      s.totalTargetRevenue += item.bookAmount;
      if (item.computedStatus === MatchStatus.MATCHED) s.totalMatched++;
      else if (item.computedStatus === MatchStatus.OVERPAID) s.totalOverpaid++;
      else if (item.computedStatus === MatchStatus.MISSING_PAYMENT) s.totalMissing++;
    });

    return s;
  }, [data]);

  const filteredResults = useMemo(() => {
    return data.filter(r => {
      const matchesFilter = filter === 'ALL' || r.computedStatus === filter;
      const matchesSearch = r.appId.includes(searchTerm);
      return matchesFilter && matchesSearch;
    });
  }, [data, filter, searchTerm]);

  const pieData = [
    { name: 'Matched (Green)', value: stats.totalMatched, color: '#10b981' }, 
    { name: 'Overpaid (Red)', value: stats.totalOverpaid, color: '#f43f5e' }, 
    { name: 'Missing (Yellow)', value: stats.totalMissing, color: '#f59e0b' }, 
  ].filter(d => d.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);
  };

  const formatDate = (date: Date | null) => {
    if (!date) return '-';
    // Use en-GB for DD/MM/YYYY format which matches input style
    return new Date(date).toLocaleDateString('en-GB'); 
  };

  const downloadCSV = () => {
    const headers = ['App ID', 'Date', 'Target (Book)', 'Paid (Gross)', 'Discount %', 'Paid (Net)', 'Difference', 'Status', 'Sources'];
    const csvContent = [
      headers.join(','),
      ...filteredResults.map(r => [
        r.appId,
        r.bookDate ? formatDate(r.bookDate) : '',
        r.bookAmount,
        r.paymentAmount,
        r.discount,
        r.netPayment,
        r.computedDifference,
        r.computedStatus,
        `"${r.sources.join('; ')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', 'audit_report.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Net Revenue" 
          value={formatCurrency(stats.totalRevenueCollected)} 
          subValue={`Target: ${formatCurrency(stats.totalTargetRevenue)}`}
          icon={<IndianRupee className="w-5 h-5 text-blue-600" />}
          trend={stats.totalRevenueCollected >= stats.totalTargetRevenue ? 'up' : 'down'}
        />
        <StatCard 
          title="Matched / Safe" 
          value={stats.totalMatched.toString()} 
          subValue="Paid <= Target"
          icon={<CheckCircle2 className="w-5 h-5 text-emerald-600" />}
          color="emerald"
        />
        <StatCard 
          title="Overpaid / Alert" 
          value={stats.totalOverpaid.toString()} 
          subValue="Paid > Target"
          icon={<AlertCircle className="w-5 h-5 text-rose-600" />}
          color="rose"
        />
        <StatCard 
          title="Missing Payments" 
