import React, { useState } from 'react';
import { ReconciliationResult, ColumnMapping, BookEntry, PaymentEntry } from './types';
import { parseRawCsv, parseRawExcel, extractBookData, extractPaymentData, guessMapping } from './services/parserService';
import { reconcileData } from './services/reconciliationService';
import { FileUpload } from './components/FileUpload';
import { ColumnMapper } from './components/ColumnMapper';
import { Dashboard } from './components/Dashboard';
import { ShieldCheck, RefreshCw, ChevronRight } from 'lucide-react';

// Type to track file processing state
interface FileData {
  file: File;
  headers: string[];
  rows: any[];
  mapping: ColumnMapping | null;
}

const App: React.FC = () => {
  // State
  const [bookFile, setBookFile] = useState<FileData | null>(null);
  const [paymentFiles, setPaymentFiles] = useState<FileData[]>([]);
  const [results, setResults] = useState<ReconciliationResult[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [step, setStep] = useState<1 | 2>(1); 

  // Handlers
  const handleBookUpload = async (files: File[]) => {
    if (files.length === 0) return;
    const file = files[0];
    try {
      const { headers, rows } = await parseRawCsv(file); // Assume CSV for books as per prompt, but could be general
      const guessed = guessMapping(headers);
      setBookFile({ file, headers, rows, mapping: guessed });
    } catch (e) {
      setError("Failed to parse Books file.");
    }
  };

  const handlePaymentUpload = async (files: File[]) => {
    const newFiles: FileData[] = [];
    for (const file of files) {
       try {
         const { headers, rows } = file.name.endsWith('csv') ? await parseRawCsv(file) : await parseRawExcel(file);
         const guessed = guessMapping(headers);
         newFiles.push({ file, headers, rows, mapping: guessed });
       } catch (e) {
         console.error("Failed to parse", file.name);
       }
    }
    setPaymentFiles(prev => [...prev, ...newFiles]);
  };

  const updateBookMapping = (m: ColumnMapping) => {
    if (bookFile) setBookFile({ ...bookFile, mapping: m });
  };

  const updatePaymentMapping = (index: number, m: ColumnMapping) => {
    setPaymentFiles(prev => prev.map((f, i) => i === index ? { ...f, mapping: m } : f));
  };

  const removePaymentFile = (index: number) => {
    setPaymentFiles(prev => prev.filter((_, i) => i !== index));
  };

  const runAudit = () => {
    if (!bookFile || !bookFile.mapping || paymentFiles.length === 0) {
      setError("Please ensure files are uploaded and columns are mapped.");
      return;
    }

    setIsProcessing(true);
    setError(null);

    // 1. Extract Typed Data
    const books: BookEntry[] = extractBookData(bookFile.rows, bookFile.mapping);
    const allPayments: PaymentEntry[] = [];

    paymentFiles.forEach(pf => {
      if (pf.mapping) {
        const pData = extractPaymentData(pf.rows, pf.mapping, pf.file.name);
        allPayments.push(...pData);
      }
    });

    if (books.length === 0) {
        setError("No valid book entries found. Please check column mapping (Debit > 0, valid App IDs).");
        setIsProcessing(false);
        return;
    }

    // 2. Reconcile
    const { results } = reconcileData(books, allPayments);
    setResults(results);
    setStep(2);
    setIsProcessing(false);
  };

  const reset = () => {
    setResults([]);
    setStep(1);
    setBookFile(null);
    setPaymentFiles([]);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <ShieldCheck className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500">
              AuditMatch Pro
            </h1>
          </div>
          {step === 2 && (
            <button onClick={reset} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 hover:text-blue-600 transition-colors">
              <RefreshCw className="w-4 h-4" /> Start New Audit
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        {step === 1 && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-bold text-slate-900">Upload Financial Records</h2>
              <p className="mt-3 text-lg text-slate-500">Upload CSVs, map columns, and verify payments against book targets.</p>
            </div>

            {/* Books Section */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">1</div>
                <h3 className="text-lg font-semibold text-slate-800">Internal Books (OFA)</h3>
              </div>

              {!bookFile ? (
                <FileUpload 
                  label="Upload Books CSV" 
                  subLabel="Contains Date, Debit Amount and App ID" 
                  accept=".csv"
                  files={[]}
                  onFilesSelected={handleBookUpload}
                  onRemoveFile={() => {}}
                />
              ) : (
                <div>
                   <div className="flex justify-between items-center p-3 bg-blue-50 rounded-lg border border-blue-100 mb-2">
                      <span className="font-medium text-blue-800">{bookFile.file.name}</span>
                      <button onClick={() => setBookFile(null)} className="text-sm text-blue-600 hover:underline">Remove</button>
                   </div>
                   {bookFile.mapping && (
                     <ColumnMapper 
                        filename={bookFile.file.name} 
                        headers={bookFile.headers} 
                        defaultMapping={bookFile.mapping} 
                        onChange={updateBookMapping}
                        type="BOOK"
                     />
                   )}
                </div>
              )}
            </div>

            {/* Payments Section */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
               <div className="flex items-center gap-3 mb-4">
                  <div className="w-8 h-8 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600 font-bold">2</div>
                  <h3 className="text-lg font-semibold text-slate-800">Company Payments</h3>
               </div>

               <FileUpload 
                  label="Add Payment Files" 
                  subLabel="Multiple CSV/Excel files allowed" 
                  accept=".csv,.xlsx,.xls"
                  multiple={true}
                  files={[]}
                  onFilesSelected={handlePaymentUpload}
                  onRemoveFile={() => {}}
                />

                <div className="space-y-4 mt-4">
                  {paymentFiles.map((pf, idx) => (
                    <div key={idx} className="border border-slate-200 rounded-lg p-4">
                       <div className="flex justify-between items-center mb-2">
                          <span className="font-medium text-slate-700">{pf.file.name}</span>
                          <button onClick={() => removePaymentFile(idx)} className="text-sm text-red-500 hover:underline">Remove</button>
                       </div>
                       {pf.mapping && (
                         <ColumnMapper 
                            filename={pf.file.name} 
                            headers={pf.headers} 
                            defaultMapping={pf.mapping} 
                            onChange={(m) => updatePaymentMapping(idx, m)}
                            type="PAYMENT"
                         />
                       )}
                    </div>
                  ))}
                </div>
            </div>

            {error && (
                <div className="p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg flex items-center gap-3">
                  <ShieldCheck className="w-5 h-5" />
                  {error}
                </div>
            )}

            <div className="flex justify-end pt-4">
                <button
                  onClick={runAudit}
                  disabled={isProcessing || !bookFile || paymentFiles.length === 0}
                  className={`
                    flex items-center gap-2 px-8 py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-500/20 transition-all
                    ${isProcessing || !bookFile || paymentFiles.length === 0
                      ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                      : 'bg-blue-600 text-white hover:bg-blue-700 hover:shadow-blue-500/30 transform hover:-translate-y-0.5'}
                  `}
                >
                  {isProcessing ? (
                    <>
                      <RefreshCw className="w-5 h-5 animate-spin" /> Processing...
                    </>
                  ) : (
                    <>
                      Run Audit <ChevronRight className="w-5 h-5" />
                    </>
                  )}
                </button>
              </div>

          </div>
        )}

        {step === 2 && <Dashboard results={results} />}
      </main>
    </div>
  );
};

export default App;

import { BookEntry, PaymentEntry, ReconciliationResult, MatchStatus, DashboardStats } from '../types';

export const reconcileData = (books: BookEntry[], payments: PaymentEntry[]): { results: ReconciliationResult[], stats: DashboardStats } => {

  // 1. Group Payments
  // Group all payments by App ID first to optimize lookups
  const paymentMap = new Map<string, PaymentEntry[]>();

  payments.forEach(p => {
    const list = paymentMap.get(p.appId) || [];
    list.push(p);
    paymentMap.set(p.appId, list);
  });

  const results: ReconciliationResult[] = [];
  let totalMatched = 0;
  let totalOverpaid = 0;
  let totalMissing = 0;
  let totalRevenueCollected = 0;
  let totalTargetRevenue = 0;

  // 2. Iterate Books
  books.forEach(book => {
    const potentialPayments = paymentMap.get(book.appId) || [];

    // Date Condition: 
    // "date of book should be less then equal to company date"
    // Equiv: Company Date >= Book Date
    const validPayments = potentialPayments.filter(p => {
      if (!book.date || !p.date) return true; // If data is missing, give benefit of doubt or handle strictly? Assuming permissive for now.

      // Normalize time for accurate date comparison
      const bDate = new Date(book.date); bDate.setHours(0,0,0,0);
      const pDate = new Date(p.date); pDate.setHours(0,0,0,0);

      return pDate >= bDate;
    });

    // Calculate Amount Paid with GST
    // Requirement: "prices from company are basic amount so add gst @ 18%"
    const amountPaid = validPayments.reduce((sum, p) => {
        const amountWithGst = p.pricePaid * 1.18; 
        return sum + amountWithGst;
    }, 0);

    const sources = Array.from(new Set(validPayments.map(p => p.sourceFile)));

    let status: MatchStatus;

    // Status logic based on Gross Paid (inclusive of GST) vs Target
    if (amountPaid === 0) {
      status = MatchStatus.MISSING_PAYMENT;
      totalMissing++;
    } else if (amountPaid > book.debit) {
      status = MatchStatus.OVERPAID;
      totalOverpaid++;
    } else {
      status = MatchStatus.MATCHED;
      totalMatched++;
    }

    totalTargetRevenue += book.debit;
    totalRevenueCollected += amountPaid;

    results.push({
      appId: book.appId,
      bookAmount: book.debit,
      paymentAmount: amountPaid, // This is now Basic + 18% GST
      difference: amountPaid - book.debit,
      status,
      sources,
      bookDate: book.date
    });
  });

  const stats: DashboardStats = {
    totalBooksRecords: books.length,
    totalPaymentsRecords: payments.length,
    totalMatched,
    totalOverpaid,
    totalMissing,
    totalRevenueCollected,
    totalTargetRevenue
  };

  return { results, stats };
};

import React, { useMemo, useState, useEffect } from 'react';
import { ReconciliationResult, MatchStatus, DashboardStats } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AlertCircle, CheckCircle2, FileWarning, Download, Percent, IndianRupee, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';

interface DashboardProps {
  results: ReconciliationResult[];
}

interface ExtendedResult extends ReconciliationResult {
  discount: number;
  netPayment: number;
  computedDifference: number;
  computedStatus: MatchStatus;
}

type SortKey = 'appId' | 'bookDate' | 'bookAmount' | 'paymentAmount' | 'discount' | 'netPayment' | 'computedStatus' | 'sources';
type SortDirection = 'asc' | 'desc';

interface SortConfig {
  key: SortKey;
  direction: SortDirection;
}

export const Dashboard: React.FC<DashboardProps> = ({ results }) => {
  const [filter, setFilter] = useState<MatchStatus | 'ALL'>('ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [globalDiscount, setGlobalDiscount] = useState<string>('0');
  const [data, setData] = useState<ExtendedResult[]>([]);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'bookDate', direction: 'desc' });

  useEffect(() => {
    // Initial calculation based on Gross
    const initialData = results.map(r => {
      // Logic:
      // Red: Paid > Target (Overpaid)
      // Yellow: Paid == 0 (Missing)
      // Green: Paid <= Target (Matched) - includes underpaid
      let status = MatchStatus.MATCHED;
      if (r.paymentAmount > r.bookAmount) status = MatchStatus.OVERPAID;
      else if (r.paymentAmount === 0) status = MatchStatus.MISSING_PAYMENT;

      return {
        ...r,
        discount: 0,
        netPayment: r.paymentAmount,
        computedDifference: r.paymentAmount - r.bookAmount,
        computedStatus: status
      };
    });
    setData(initialData);
  }, [results]);

  const recalculateRow = (item: ExtendedResult, discountVal: number) => {
    // Payment Amount here already includes 18% GST from the service
    // Net = (Basic + GST) * (1 - Discount%)
    const net = item.paymentAmount * (1 - discountVal / 100);
    const diff = net - item.bookAmount;

    let status = MatchStatus.MATCHED;
    if (net > item.bookAmount) status = MatchStatus.OVERPAID;
    else if (net === 0 && item.paymentAmount === 0) status = MatchStatus.MISSING_PAYMENT;

    return {
      ...item,
      discount: discountVal,
      netPayment: net,
      computedDifference: diff,
      computedStatus: status
    };
  };

  const applyGlobalDiscount = () => {
    const val = parseFloat(globalDiscount) || 0;
    setData(prev => prev.map(item => recalculateRow(item, val)));
  };

  const handleRowDiscountChange = (appId: string, valStr: string) => {
    const val = parseFloat(valStr) || 0;
    setData(prev => prev.map(item => item.appId === appId ? recalculateRow(item, val) : item));
  };

  const handleSort = (key: SortKey) => {
    setSortConfig(current => ({
      key,
      direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const stats = useMemo(() => {
    const s: DashboardStats = {
      totalBooksRecords: data.length,
      totalPaymentsRecords: 0,
      totalMatched: 0,
      totalOverpaid: 0,
      totalMissing: 0,
      totalRevenueCollected: 0,
      totalTargetRevenue: 0
    };

    data.forEach(item => {
      s.totalRevenueCollected += item.netPayment;
      s.totalTargetRevenue += item.bookAmount;
      if (item.computedStatus === MatchStatus.MATCHED) s.totalMatched++;
      else if (item.computedStatus === MatchStatus.OVERPAID) s.totalOverpaid++;
      else if (item.computedStatus === MatchStatus.MISSING_PAYMENT) s.totalMissing++;
    });

    return s;
  }, [data]);

  const filteredAndSortedResults = useMemo(() => {
    // 1. Filter
    let processed = data.filter(r => {
      const matchesFilter = filter === 'ALL' || r.computedStatus === filter;
      const matchesSearch = r.appId.includes(searchTerm);
      return matchesFilter && matchesSearch;
    });

    // 2. Sort
    return processed.sort((a, b) => {
      let valA: any = a[sortConfig.key];
      let valB: any = b[sortConfig.key];

      // Handle specific types
      if (sortConfig.key === 'sources') {
        valA = a.sources.join(', ');
        valB = b.sources.join(', ');
      }

      if (valA === valB) return 0;

      // Handle nulls
      if (valA === null || valA === undefined) return 1;
      if (valB === null || valB === undefined) return -1;

      const compareResult = valA < valB ? -1 : 1;
      return sortConfig.direction === 'asc' ? compareResult : -compareResult;
    });
  }, [data, filter, searchTerm, sortConfig]);

  const pieData = [
    { name: 'Matched (Green)', value: stats.totalMatched, color: '#10b981' }, 
    { name: 'Overpaid (Red)', value: stats.totalOverpaid, color: '#f43f5e' }, 
    { name: 'Missing (Yellow)', value: stats.totalMissing, color: '#f59e0b' }, 
  ].filter(d => d.value > 0);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val);
  };

  const formatDate = (date: Date | null) => {
    if (!date) return '-';
    return new Date(date).toLocaleDateString('en-GB'); 
  };

  const downloadCSV = () => {
    const headers = ['App ID', 'Date', 'Target (Book)', 'Paid (Gross + GST)', 'Discount %', 'Paid (Net)', 'Difference', 'Status', 'Sources'];
    const csvContent = [
      headers.join(','),
      ...filteredAndSortedResults.map(r => [
        r.appId,
        r.bookDate ? formatDate(r.bookDate) : '',
        r.bookAmount,
        r.paymentAmount,
        r.discount,
        r.netPayment,
        r.computedDifference,
        r.computedStatus,
        `"${r.sources.join('; ')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', 'audit_report.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const SortIcon = ({ column }: { column: SortKey }) => {
    if (sortConfig.key !== column) return <ArrowUpDown className="w-3 h-3 text-slate-300 ml-1" />;
    return sortConfig.direction === 'asc' 
      ? <ArrowUp className="w-3 h-3 text-blue-600 ml-1" />
      : <ArrowDown className="w-3 h-3 text-blue-600 ml-1" />;
  };

  const HeaderCell = ({ label, column, align = 'left' }: { label: string, column: SortKey, align?: 'left'|'center'|'right' }) => (
    <th 
      className={`px-4 py-3 font-medium cursor-pointer hover:bg-slate-100 transition-colors select-none text-${align}`}
      onClick={() => handleSort(column)}
    >
      <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
        {label} <SortIcon column={column} />
      </div>
    </th>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Net Revenue" 
          value={formatCurrency(stats.totalRevenueCollected)} 
          subValue={`Target: ${formatCurrency(stats.totalTargetRevenue)}`}
          icon={<IndianRupee className="w-5 h-5 text-blue-600" />}
          trend={stats.totalRevenueCollected >= stats.totalTargetRevenue ? 'up' : 'down'}
        />
        <StatCard 
          title="Matched / Safe" 
          value={stats.totalMatched.toString()} 
          subValue="Paid <= Target"
          icon={<CheckCircle2 className="w-5 h-5 text-emerald-600" />}
          color="emerald"
        />
        <StatCard 
          title="Overpaid / Alert" 
          value={stats.totalOverpaid.toString()} 
          subValue="Paid > Target"
          icon={<AlertCircle className="w-5 h-5 text-rose-600" />}
          color="rose"
        />
        <StatCard 
          title="Missing Payments" 
          value={stats.totalMissing.toString()} 
          subValue="No valid payment found"
          icon={<FileWarning className="w-5 h-5 text-amber-600" />}
          color="amber"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm lg:col-span-1 flex flex-col">
           <h3 className="text-lg font-semibold text-slate-800 mb-4">Settings</h3>
           <div className="p-4 bg-slate-50 rounded-lg border border-slate-200 mb-6">
              <label className="block text-sm font-medium text-slate-700 mb-2">Global Discount (%)</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <input 
                    type="number" 
                    min="0" 
                    max="100"
                    step="0.1"
                    className="w-full pl-3 pr-8 py-2 border border-slate-300 bg-white text-slate-900 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 font-medium"
                    value={globalDiscount}
                    onChange={(e) => setGlobalDiscount(e.target.value)}
                  />
                  <Percent className="absolute right-2.5 top-2.5 w-4 h-4 text-slate-400" />
                </div>
                <button 
                  onClick={applyGlobalDiscount}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors"
                >
                  Apply
                </button>
              </div>
              <p className="text-xs text-slate-500 mt-2">Discount reduces the 'Paid' amount. Gross Paid includes 18% GST.</p>
           </div>

          <h3 className="text-lg font-semibold text-slate-800 mb-4">Status Distribution</h3>
          <div className="flex-1 min-h-[200px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Top Overpaid Apps (Net)</h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={data
                  .filter(r => r.computedDifference > 0) // Overpaid means difference > 0
                  .sort((a, b) => b.computedDifference - a.computedDifference)
                  .slice(0, 10)}
                layout="vertical"
                margin={{ top: 5, right: 30, left: 40, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} />
                <XAxis type="number" tickFormatter={(val) => `₹${val}`} />
                <YAxis dataKey="appId" type="category" width={80} />
                <Tooltip formatter={(value) => formatCurrency(Number(value))} />
                <Bar dataKey="computedDifference" fill="#f43f5e" radius={[0, 4, 4, 0]} name="Excess Paid" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-5 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <h3 className="text-lg font-bold text-slate-800">Audit Details</h3>

          <div className="flex flex-col sm:flex-row gap-3">
             <input 
              type="text" 
              placeholder="Search App ID..." 
              className="px-3 py-2 border border-slate-300 bg-white text-slate-900 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <select 
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
              value={filter}
              onChange={(e) => setFilter(e.target.value as any)}
            >
              <option value="ALL">All Statuses</option>
              <option value={MatchStatus.MATCHED}>Matched (Green)</option>
              <option value={MatchStatus.OVERPAID}>Overpaid (Red)</option>
              <option value={MatchStatus.MISSING_PAYMENT}>Missing (Yellow)</option>
            </select>
            <button 
              onClick={downloadCSV}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition-colors"
            >
              <Download className="w-4 h-4" /> Export
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
              <tr>
                <HeaderCell label="App ID" column="appId" />
                <HeaderCell label="Book Date" column="bookDate" />
                <HeaderCell label="Target (Book)" column="bookAmount" align="right" />
                <HeaderCell label="Gross Paid (Inc. GST)" column="paymentAmount" align="right" />
                <HeaderCell label="Disc %" column="discount" align="center" />
                <HeaderCell label="Net Paid" column="netPayment" align="right" />
                <HeaderCell label="Status" column="computedStatus" align="center" />
                <HeaderCell label="Sources" column="sources" />
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredAndSortedResults.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-8 text-center text-slate-500">
                    No records found matching criteria.
                  </td>
                </tr>
              ) : (
                filteredAndSortedResults.map((row) => (
                  <tr key={row.appId} className="hover:bg-slate-50 transition-colors">
                    <td className="px-4 py-3 font-medium text-slate-900">{row.appId}</td>
                    <td className="px-4 py-3 text-slate-500 whitespace-nowrap">{formatDate(row.bookDate)}</td>
                    <td className="px-4 py-3 text-right font-mono text-slate-600">{formatCurrency(row.bookAmount)}</td>
                    <td className="px-4 py-3 text-right font-mono text-slate-400" title="Includes 18% GST">{formatCurrency(row.paymentAmount)}</td>
                    <td className="px-4 py-3 text-center">
                      <input 
                        type="number" 
                        min="0"
                        max="100"
                        className="w-16 px-2 py-1 text-center border border-slate-200 rounded text-xs focus:ring-2 focus:ring-blue-500 focus:outline-none bg-white"
                        value={row.discount}
                        onClick={(e) => e.stopPropagation()} // Prevent row click issues
                        onChange={(e) => handleRowDiscountChange(row.appId, e.target.value)}
                      />
                    </td>
                    <td className="px-4 py-3 text-right font-mono font-medium text-slate-800">{formatCurrency(row.netPayment)}</td>
                    <td className="px-4 py-3 text-center">
                      <StatusBadge status={row.computedStatus} />
                    </td>
